/** Prefix rules applied when no exact match exists. */
export const LEGACY_PREFIX_RULES: Array<{ test: RegExp; to: string }> = [
  { test: /^\/service\//, to: "/services" },
  { test: /^\/services\//, to: "/services" },
  { test: /^\/products?\//, to: "/products/trade-show-exhibit-rentals" },
  { test: /^\/product-category\//, to: "/portable-booths" },
  { test: /^\/shop\//, to: "/portable-booths" },
  { test: /^\/rent(al)?-/, to: "/rent-a-booth" },
  { test: /^\/best-portable-trade-show-displays-exhibits-booth-rentals/, to: "/portable-booths" },
  { test: /^\/portable/, to: "/portable-booths" },
  { test: /^\/landing\//, to: "/" },
  { test: /-trade-show-displays-exhibits$/, to: "/venues" },
  { test: /^\/(category|tag|author)\//, to: "/blog" },
];

/** Normalises a request path: strips trailing slash, lowercases. */
export const normaliseLegacyPath = (p: string) => {
  const clean = p.split("?")[0].split("#")[0].toLowerCase().replace(/\/+$/, "");
  return clean || "/";
};

export const resolveLegacyRedirect = (pathname: string): string | undefined => {
  const p = normaliseLegacyPath(pathname);
  const exact = LEGACY_REDIRECTS[p];
  if (exact) return exact;
  const rule = LEGACY_PREFIX_RULES.find((r) => r.test.test(p));
  return rule?.to;
};
